#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QApplication>
#include <QCheckBox>
#include <QDialog>
#include <QDialogButtonBox>
#include <QPushButton>
#include <QRadioButton>
#include <QTableView>
#include <QTemporaryDir>
#include <QTest>
#include <QTimer>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void select(QTableView& grid,WorksheetModel& model,int row,int col,int lastRow,int lastCol){grid.setCurrentIndex(model.index(row,col));grid.selectionModel()->select(QItemSelection(model.index(row,col),model.index(lastRow,lastCol)),QItemSelectionModel::ClearAndSelect);grid.setFocus();QApplication::processEvents();}
void nativePaste(QTableView& grid,const char* mode,bool skip){bool chosen=false;QTimer::singleShot(0,[&]{if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget())){auto* radio=dialog->findChild<QRadioButton*>("pasteSpecial."+QString::fromLatin1(mode));auto* transpose=dialog->findChild<QCheckBox*>("pasteSpecial.transpose");auto* skipBlanks=dialog->findChild<QCheckBox*>("pasteSpecial.skipBlanks");if(radio&&transpose&&skipBlanks){radio->click();transpose->setChecked(true);skipBlanks->setChecked(skip);chosen=true;dialog->findChild<QDialogButtonBox*>("pasteSpecial.buttons")->button(QDialogButtonBox::Ok)->click();}else dialog->reject();}});QTest::keyClick(&grid,Qt::Key_V,Qt::ControlModifier|Qt::AltModifier);require(chosen,"Ctrl+Alt+V opens the real Paste Special dialog and accepts mode, Transpose and Skip blanks independently");}
void formats(){MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());Json ops=Json::array();for(int row=0;row<3;++row)for(int col=0;col<2;++col){ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",row+1},{"col",col+1},{"input",row==2&&col==0?"":std::to_string(row*2+col+1)},{"style",{{"fill",col==0?"#ff0000":"#0000ff"},{"numberFormat","0.00"}}}});ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",col+6},{"col",row+4},{"input","99"},{"style",{{"fill","#00ff00"},{"bold",true}}}});}require(model->apply(ops),"seed a rectangular source and destination with different inputs and formatting");select(*grid,*model,0,0,2,1);QTest::keyClick(grid,Qt::Key_C,Qt::ControlModifier);select(*grid,*model,5,3,5,3);const auto before=window.currentSession().snapshot();nativePaste(*grid,"formats",true);require(model->raw(5,3)=="99"&&model->raw(6,5)=="99","Formats plus Transpose never changes destination inputs");require(model->cellStyle(5,3).value("fill",std::string())=="#ff0000"&&model->cellStyle(6,4).value("fill",std::string())=="#0000ff"&&model->cellStyle(5,5).value("fill",std::string())=="#00ff00"&&model->cellStyle(6,5).value("fill",std::string())=="#0000ff","Formats transpose the complete 3-by-2 source and Skip blanks retains the blank source's destination formatting");require(window.executeCommand("undo")&&window.currentSession().snapshot().at("sheets")==before.at("sheets"),"compound Formats paste is one undoable edit");}
void formulas(bool values){MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());Json ops=Json::array();for(int row=0;row<2;++row){ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",row+1},{"col",1},{"input","=C"+std::to_string(row+1)},{"style",{{"fill","#ff0000"}}}});ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",row+1},{"col",3},{"input",std::to_string(7+row)}});ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",8},{"col",row+4},{"input","99"},{"style",{{"italic",true},{"fontSize",19}}}});}require(model->apply(ops),"seed formula and numeric sources");window.recalculateNow();select(*grid,*model,0,0,1,0);QTest::keyClick(grid,Qt::Key_C,Qt::ControlModifier);select(*grid,*model,7,3,7,3);const auto before=window.currentSession().snapshot();nativePaste(*grid,values?"values":"formulas",false);const auto numericInput=[&](int col,double expected){bool number=false;const auto input=model->raw(7,col);const double value=input.toDouble(&number);return number&&value==expected&&!input.startsWith('=')&&!input.startsWith('\'');};require(values?(numericInput(3,7)&&numericInput(4,8)):(model->raw(7,3)=="=F8"&&model->raw(7,4)=="=G8"),"selected Formulas/Values mode is retained while transposing, with relative formulas or typed calculated values");require(model->cellStyle(7,3).value("italic",false)&&model->cellStyle(7,4).value("fontSize",0)==19&&!model->cellStyle(7,3).contains("fill"),"Formulas/Values plus Transpose retains destination formatting");require(window.executeCommand("undo")&&window.currentSession().snapshot().at("sheets")==before.at("sheets"),"compound formula/value paste is one undoable edit");}
void guarded(bool arithmetic){MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"4",Qt::EditRole)&&model->setData(model->index(3,3),"9",Qt::EditRole),"seed distinct guard source/destination");select(*grid,*model,0,0,0,0);QTest::keyClick(grid,Qt::Key_C,Qt::ControlModifier);select(*grid,*model,3,3,3,3);const auto before=window.currentSession().snapshot();bool chosen=false;QTimer::singleShot(0,[&]{if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget())){auto* radio=dialog->findChild<QRadioButton*>(arithmetic?"pasteSpecial.values":"pasteSpecial.validation");if(radio){radio->click();if(arithmetic)dialog->findChild<QRadioButton*>("pasteSpecial.operation.add")->click();chosen=true;dialog->accept();}else dialog->reject();}});QTest::keyClick(grid,Qt::Key_V,Qt::ControlModifier|Qt::AltModifier);require(chosen,"select an advanced native paste choice");require(window.currentSession().snapshot()==before&&window.lastError().contains("not supported",Qt::CaseInsensitive),"unsupported native paste choices fail explicitly before changing destination cells or Undo history");}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const auto mode=argc>1?std::string(argv[1]):std::string("formats");if(mode=="formats")formats();else if(mode=="advanced"||mode=="operation")guarded(mode=="operation");else formulas(mode=="values");std::cout<<"Compound Paste Special passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
